param(
    [string]$DbHost = "localhost",
    [int]$DbPort = 5432,
    [string]$Database = "postgres",
    [string]$DbLoginUser = "postgres",
    [string]$DatabasePwd = "postgres",
    [string]$DbUser = "paynest_app",
    [string]$DbPassword = "paynest_app",
    [string]$TenantId = "e2e",
    [string]$TenantName = "Default E2E Test Tenant",
    [string]$TenantSchema = "tenant_$TenantId",
    [string]$TenantTimeZone = "UTC",
    [string]$DefaultAdminAccountId = "ADMIN0000000001",
    [string]$DefaultAdminLoginId = "superadmin",
    [string]$DefaultAdminPassword = "Admin@123",
    [string]$DefaultAdminEmail = "superadmin@paynest.local",
    [string]$DefaultAdminMobile = "+10000000000",
    [string]$DefaultAdminAuthSalt = "paynest-default-admin-salt"
)

$ErrorActionPreference = "Stop"

function Write-DbBootstrapLog {
    param(
        [string]$Message
    )

    $timestamp = Get-Date -Format "yyyy-MM-dd HH:mm:ss.fff zzz"
    Write-Host "[$timestamp] [db-bootstrap] $Message"
}

function Invoke-PsqlCommand {
    param(
        [string[]]$Arguments,
        [string]$StepName
    )

    Write-DbBootstrapLog "Starting psql step '$StepName'. arguments=$($Arguments -join ' ')"
    $startedAt = Get-Date
    & psql @Arguments
    $exitCode = $LASTEXITCODE
    $durationMs = [int]((Get-Date) - $startedAt).TotalMilliseconds
    Write-DbBootstrapLog "Finished psql step '$StepName'. exitCode=$exitCode durationMs=$durationMs"

    if ($exitCode -ne 0) {
        throw "psql step '$StepName' exited with code $exitCode"
    }
}

Write-DbBootstrapLog "Bootstrap parameters: dbHost=$DbHost dbPort=$DbPort database=$Database dbLoginUser=$DbLoginUser dbUser=$DbUser tenantId=$TenantId tenantSchema=$TenantSchema tenantName='$TenantName' tenantTimeZone=$TenantTimeZone"

if (-not (Get-Command psql -ErrorAction SilentlyContinue)) {
    throw "psql was not found on PATH. Install PostgreSQL client tools or add psql.exe to PATH."
}

$psqlCommand = Get-Command psql
Write-DbBootstrapLog "Found psql. path=$($psqlCommand.Source)"

$env:PGPASSWORD = $DatabasePwd
$sqlFile = Join-Path ([System.IO.Path]::GetTempPath()) ("paynest-bootstrap-{0}.sql" -f ([guid]::NewGuid()))
Write-DbBootstrapLog "Generated temporary SQL file path. sqlFile=$sqlFile"
$sha256 = [System.Security.Cryptography.SHA256]::Create()
$adminCredentialBytes = [System.Text.Encoding]::UTF8.GetBytes($DefaultAdminPassword + $DefaultAdminAuthSalt)
$DefaultAdminPasswordHash = (($sha256.ComputeHash($adminCredentialBytes) | ForEach-Object { $_.ToString("x2") }) -join "")

$sql = @"
BEGIN;

CREATE SCHEMA IF NOT EXISTS $TenantSchema;

CREATE TABLE IF NOT EXISTS public.tenant_registry (
    tenant_id VARCHAR(50) PRIMARY KEY,
    tenant_name VARCHAR(100),
    schema_name VARCHAR(100) NOT NULL,
    iana_time_zone VARCHAR(100),
    status VARCHAR(20),
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

INSERT INTO public.tenant_registry (
    tenant_id,
    tenant_name,
    schema_name,
    iana_time_zone,
    status,
    created_at,
    updated_at
)
VALUES (
    '$TenantId',
    '$TenantName',
    '$TenantSchema',
    '$TenantTimeZone',
    'ACTIVE',
    CURRENT_TIMESTAMP,
    CURRENT_TIMESTAMP
)
ON CONFLICT (tenant_id) DO UPDATE
SET tenant_name = EXCLUDED.tenant_name,
    schema_name = EXCLUDED.schema_name,
    iana_time_zone = EXCLUDED.iana_time_zone,
    status = 'ACTIVE',
    updated_at = CURRENT_TIMESTAMP;

CREATE TABLE IF NOT EXISTS $TenantSchema.enumerations (
    id BIGSERIAL PRIMARY KEY,
    enum_type VARCHAR(50) NOT NULL,
    enum_code VARCHAR(50) NOT NULL,
    enum_value VARCHAR(100) NOT NULL,
    parent_enum_id BIGINT,
    description VARCHAR(255),
    display_order INTEGER DEFAULT 0,
    is_active BOOLEAN DEFAULT TRUE,
    is_system BOOLEAN DEFAULT TRUE,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP,
    field1 VARCHAR(250),
    field2 VARCHAR(250),
    field3 VARCHAR(250),
    field4 VARCHAR(250),
    field5 VARCHAR(250),
    CONSTRAINT uk_enumerations_type_code UNIQUE (enum_type, enum_code)
);

ALTER TABLE $TenantSchema.enumerations
    ADD COLUMN IF NOT EXISTS parent_enum_id BIGINT;

ALTER TABLE $TenantSchema.enumerations
    ADD COLUMN IF NOT EXISTS field1 VARCHAR(250);

ALTER TABLE $TenantSchema.enumerations
    ADD COLUMN IF NOT EXISTS field2 VARCHAR(250);

ALTER TABLE $TenantSchema.enumerations
    ADD COLUMN IF NOT EXISTS field3 VARCHAR(250);

ALTER TABLE $TenantSchema.enumerations
    ADD COLUMN IF NOT EXISTS field4 VARCHAR(250);

ALTER TABLE $TenantSchema.enumerations
    ADD COLUMN IF NOT EXISTS field5 VARCHAR(250);

DO `$`$
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM pg_constraint
        WHERE conname = 'fk_enumerations_parent_enum'
          AND conrelid = '$TenantSchema.enumerations'::regclass
    ) THEN
        ALTER TABLE $TenantSchema.enumerations
            ADD CONSTRAINT fk_enumerations_parent_enum
            FOREIGN KEY (parent_enum_id) REFERENCES $TenantSchema.enumerations(id);
    END IF;
END
`$`$;

CREATE TABLE IF NOT EXISTS $TenantSchema.country_subdivision (
    id BIGSERIAL PRIMARY KEY,
    country_id BIGINT NOT NULL,
    code VARCHAR(50) NOT NULL,
    name VARCHAR(150) NOT NULL,
    type VARCHAR(50) NOT NULL,
    parent_id BIGINT,
    status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE',
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP,
    CONSTRAINT fk_country_subdivision_country FOREIGN KEY (country_id) REFERENCES $TenantSchema.enumerations(id),
    CONSTRAINT fk_country_subdivision_parent FOREIGN KEY (parent_id) REFERENCES $TenantSchema.country_subdivision(id)
);

CREATE UNIQUE INDEX IF NOT EXISTS uk_country_subdivision_country_code
    ON $TenantSchema.country_subdivision (country_id, code);

CREATE INDEX IF NOT EXISTS idx_country_subdivision_country
    ON $TenantSchema.country_subdivision (country_id);

CREATE TABLE IF NOT EXISTS $TenantSchema.city (
    id BIGSERIAL PRIMARY KEY,
    country_id BIGINT NOT NULL,
    subdivision_id BIGINT,
    name VARCHAR(150) NOT NULL,
    code VARCHAR(100),
    latitude NUMERIC(10, 6),
    longitude NUMERIC(10, 6),
    timezone VARCHAR(100),
    status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE',
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP,
    CONSTRAINT fk_city_country FOREIGN KEY (country_id) REFERENCES $TenantSchema.enumerations(id),
    CONSTRAINT fk_city_subdivision FOREIGN KEY (subdivision_id) REFERENCES $TenantSchema.country_subdivision(id)
);

CREATE UNIQUE INDEX IF NOT EXISTS uk_city_country_subdivision_code
    ON $TenantSchema.city (country_id, (COALESCE(subdivision_id, 0)), code)
    WHERE code IS NOT NULL;

CREATE INDEX IF NOT EXISTS idx_city_country
    ON $TenantSchema.city (country_id);

CREATE INDEX IF NOT EXISTS idx_city_subdivision
    ON $TenantSchema.city (subdivision_id);

CREATE TABLE IF NOT EXISTS $TenantSchema.supported_languages (
    id BIGSERIAL PRIMARY KEY,
    language_code VARCHAR(10) NOT NULL UNIQUE,
    language_name VARCHAR(100) NOT NULL,
    display_order INTEGER DEFAULT 0,
    is_default BOOLEAN DEFAULT FALSE,
    is_active BOOLEAN DEFAULT TRUE,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP
);

ALTER TABLE $TenantSchema.supported_languages
    ADD COLUMN IF NOT EXISTS display_order INTEGER DEFAULT 0;

CREATE TABLE IF NOT EXISTS $TenantSchema.account (
    account_id TEXT PRIMARY KEY,
    account_type VARCHAR(50) NOT NULL,
    account_code VARCHAR(100),
    first_name VARCHAR(255),
    last_name VARCHAR(255),
    mobile_number VARCHAR(50),
    email VARCHAR(255),
    address TEXT,
    gender VARCHAR(50),
    date_of_birth DATE,
    preferred_lang VARCHAR(20),
    nationality VARCHAR(100),
    ssn VARCHAR(100),
    remarks TEXT,
    attr1 TEXT,
    attr2 TEXT,
    attr3 TEXT,
    attr4 TEXT,
    attr5 TEXT,
    attr6 TEXT,
    attr7 TEXT,
    attr8 TEXT,
    attr9 TEXT,
    attr10 TEXT,
    kyc_status VARCHAR(50),
    status VARCHAR(20),
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP,
    created_by VARCHAR(255),
    updated_by VARCHAR(255)
);

ALTER TABLE $TenantSchema.account
    ADD COLUMN IF NOT EXISTS account_code VARCHAR(100);

CREATE UNIQUE INDEX IF NOT EXISTS uk_account_mobile_number
    ON $TenantSchema.account (mobile_number)
    WHERE mobile_number IS NOT NULL;

CREATE UNIQUE INDEX IF NOT EXISTS uk_account_account_code_active
    ON $TenantSchema.account (account_code)
