);

ALTER TABLE $TenantSchema.account_biller_info
    ADD COLUMN IF NOT EXISTS biller_sub_category VARCHAR(100);

ALTER TABLE $TenantSchema.account_biller_info
    ADD COLUMN IF NOT EXISTS biller_config JSONB;

ALTER TABLE $TenantSchema.account_biller_info
    ADD COLUMN IF NOT EXISTS biller_settings JSONB;

ALTER TABLE $TenantSchema.account_biller_info
    ADD COLUMN IF NOT EXISTS created_on TIMESTAMP DEFAULT CURRENT_TIMESTAMP;

ALTER TABLE $TenantSchema.account_biller_info
