ALTER TABLE $TenantSchema.account_biller_info
    ADD COLUMN IF NOT EXISTS modified_on TIMESTAMP;

ALTER TABLE $TenantSchema.account_biller_info
    ADD COLUMN IF NOT EXISTS modified_by VARCHAR(100);

ALTER TABLE $TenantSchema.account_biller_info
