    status VARCHAR(30) DEFAULT 'ACTIVE',
    created_on TIMESTAMP DEFAULT NOW(),
    updated_at TIMESTAMP DEFAULT NOW(),
    field1 VARCHAR(250) NULL,
    field2 VARCHAR(250) NULL,
