    CONSTRAINT fk_wallet_balance_wallet FOREIGN KEY (wallet_id) REFERENCES $TenantSchema.wallet(wallet_id)
);

CREATE TABLE IF NOT EXISTS $TenantSchema.wallet_restriction (
    wallet_id BIGINT PRIMARY KEY,
