    verification_status VARCHAR(50) NOT NULL DEFAULT 'PENDING',
    verified_by VARCHAR(255),
    verified_at TIMESTAMP,
    rejection_reason TEXT,
    is_primary BOOLEAN DEFAULT FALSE,
    is_active BOOLEAN DEFAULT TRUE,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_kyc_document_account FOREIGN KEY (account_id) REFERENCES $TenantSchema.account(account_id)
);

CREATE TABLE IF NOT EXISTS $TenantSchema.document_category (
    category_id BIGSERIAL PRIMARY KEY,
    category_code VARCHAR(50) NOT NULL UNIQUE,
    category_name VARCHAR(100) NOT NULL,
    description VARCHAR(255),
    is_active BOOLEAN NOT NULL DEFAULT TRUE,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS $TenantSchema.document_type (
    document_type_id BIGSERIAL PRIMARY KEY,
    category_id BIGINT NOT NULL,
    type_code VARCHAR(75) NOT NULL UNIQUE,
    type_name VARCHAR(150) NOT NULL,
    description VARCHAR(255),
    multiple_allowed BOOLEAN NOT NULL DEFAULT TRUE,
    verification_required BOOLEAN NOT NULL DEFAULT FALSE,
    is_active BOOLEAN NOT NULL DEFAULT TRUE,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_document_type_category FOREIGN KEY (category_id)
        REFERENCES $TenantSchema.document_category(category_id)
);

CREATE TABLE IF NOT EXISTS $TenantSchema.document_type_entity (
    document_type_id BIGINT NOT NULL,
    entity_type VARCHAR(30) NOT NULL,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (document_type_id, entity_type),
    CONSTRAINT fk_document_type_entity_type FOREIGN KEY (document_type_id)
        REFERENCES $TenantSchema.document_type(document_type_id),
    CONSTRAINT chk_document_type_entity CHECK (entity_type IN ('CUSTOMER', 'MERCHANT', 'AGENT', 'TRANSACTION'))
);

CREATE TABLE IF NOT EXISTS $TenantSchema.stored_document (
    document_id UUID PRIMARY KEY,
    tenant_id VARCHAR(100) NOT NULL,
    document_type_id BIGINT NOT NULL,
    document_name VARCHAR(255) NOT NULL,
    original_file_name VARCHAR(255) NOT NULL,
    content_type VARCHAR(150) NOT NULL,
    file_size_bytes BIGINT NOT NULL,
    checksum_sha256 VARCHAR(64),
    gridfs_bucket_name VARCHAR(100) NOT NULL DEFAULT 'fs',
    gridfs_file_id VARCHAR(64) NOT NULL UNIQUE,
    thumbnail_gridfs_file_id VARCHAR(64),
    thumbnail_content_type VARCHAR(150),
    thumbnail_size_bytes BIGINT,
    status VARCHAR(30) NOT NULL DEFAULT 'ACTIVE',
    uploaded_by VARCHAR(100) NOT NULL,
    uploaded_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    deleted_at TIMESTAMP,
    CONSTRAINT fk_stored_document_type FOREIGN KEY (document_type_id)
        REFERENCES $TenantSchema.document_type(document_type_id),
    CONSTRAINT chk_stored_document_size CHECK (file_size_bytes >= 0),
    CONSTRAINT chk_stored_document_thumbnail_size CHECK (thumbnail_size_bytes IS NULL OR thumbnail_size_bytes >= 0),
    CONSTRAINT chk_stored_document_status CHECK (status IN ('ACTIVE', 'DELETED', 'QUARANTINED', 'UPLOAD_FAILED'))
);

ALTER TABLE $TenantSchema.stored_document
    ADD COLUMN IF NOT EXISTS thumbnail_gridfs_file_id VARCHAR(64),
    ADD COLUMN IF NOT EXISTS thumbnail_content_type VARCHAR(150),
    ADD COLUMN IF NOT EXISTS thumbnail_size_bytes BIGINT;

CREATE UNIQUE INDEX IF NOT EXISTS uk_stored_document_thumbnail_gridfs_file_id
    ON $TenantSchema.stored_document (thumbnail_gridfs_file_id)
    WHERE thumbnail_gridfs_file_id IS NOT NULL;

CREATE TABLE IF NOT EXISTS $TenantSchema.document_reference (
    document_reference_id BIGSERIAL PRIMARY KEY,
    document_id UUID NOT NULL,
    entity_type VARCHAR(30) NOT NULL,
    entity_id VARCHAR(100) NOT NULL,
    reference_role VARCHAR(30) NOT NULL DEFAULT 'OWNER',
    is_primary BOOLEAN NOT NULL DEFAULT FALSE,
    is_active BOOLEAN NOT NULL DEFAULT TRUE,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_document_reference_document FOREIGN KEY (document_id)
        REFERENCES $TenantSchema.stored_document(document_id),
    CONSTRAINT uq_document_reference UNIQUE (document_id, entity_type, entity_id, reference_role),
    CONSTRAINT chk_document_reference_entity CHECK (entity_type IN ('CUSTOMER', 'MERCHANT', 'AGENT', 'TRANSACTION')),
    CONSTRAINT chk_document_reference_role CHECK (reference_role IN ('OWNER', 'SUBJECT', 'ATTACHMENT', 'AUTHORIZED_VIEWER'))
);

CREATE INDEX IF NOT EXISTS idx_document_type_category
    ON $TenantSchema.document_type (category_id);

CREATE INDEX IF NOT EXISTS idx_stored_document_tenant_type
    ON $TenantSchema.stored_document (tenant_id, document_type_id, uploaded_at DESC);

CREATE INDEX IF NOT EXISTS idx_stored_document_checksum
    ON $TenantSchema.stored_document (checksum_sha256);

CREATE INDEX IF NOT EXISTS idx_document_reference_entity
    ON $TenantSchema.document_reference (entity_type, entity_id, is_active);

CREATE INDEX IF NOT EXISTS idx_document_reference_document
    ON $TenantSchema.document_reference (document_id);

ALTER TABLE $TenantSchema.kyc_document
    ADD COLUMN IF NOT EXISTS stored_document_id UUID REFERENCES $TenantSchema.stored_document(document_id);

INSERT INTO $TenantSchema.document_category (category_code, category_name, is_active)
VALUES
    ('IDENTITY', 'Identity Documents', TRUE),
    ('FINANCIAL', 'Financial Documents', TRUE),
    ('LEGAL', 'Legal Documents', TRUE),
    ('SUPPORTING', 'Supporting Documents', TRUE)
ON CONFLICT (category_code) DO UPDATE SET
    category_name = EXCLUDED.category_name,
    is_active = EXCLUDED.is_active,
    updated_at = CURRENT_TIMESTAMP;

INSERT INTO $TenantSchema.document_type (
    category_id,
    type_code,
    type_name,
    multiple_allowed,
    verification_required,
    is_active
)
SELECT
    category.category_id,
    seed.type_code,
    seed.type_name,
    seed.multiple_allowed,
    seed.verification_required,
    TRUE
FROM (
    VALUES
        ('IDENTITY', 'AADHAAR', 'Aadhaar Card', TRUE, TRUE),
        ('IDENTITY', 'PAN', 'PAN Card', TRUE, TRUE),
        ('IDENTITY', 'PASSPORT', 'Passport', TRUE, TRUE),
        ('IDENTITY', 'GST_CERTIFICATE', 'GST Certificate', TRUE, TRUE),
        ('IDENTITY', 'BUSINESS_REGISTRATION', 'Business Registration', TRUE, TRUE),
        ('IDENTITY', 'NATIONAL_ID', 'National ID', TRUE, TRUE),
        ('IDENTITY', 'TAX_ID', 'Tax ID', TRUE, TRUE),
        ('IDENTITY', 'DRIVING_LICENSE', 'Driving License', TRUE, TRUE),
        ('IDENTITY', 'ADDRESS_PROOF', 'Address Proof', TRUE, TRUE),
        ('IDENTITY', 'SELFIE', 'Selfie', TRUE, TRUE),
        ('FINANCIAL', 'BANK_STATEMENT', 'Bank Statement', TRUE, FALSE),
        ('FINANCIAL', 'CANCELLED_CHEQUE', 'Cancelled Cheque', TRUE, FALSE),
        ('FINANCIAL', 'INVOICE', 'Invoice', TRUE, FALSE),
        ('FINANCIAL', 'RECEIPT', 'Receipt', TRUE, FALSE),
        ('FINANCIAL', 'SETTLEMENT_REPORT', 'Settlement Report', TRUE, FALSE),
        ('FINANCIAL', 'BANK_ACCOUNT_PROOF', 'Bank Account Proof', TRUE, TRUE),
        ('LEGAL', 'MERCHANT_AGREEMENT', 'Merchant Agreement', TRUE, TRUE),
        ('LEGAL', 'CUSTOMER_CONSENT', 'Customer Consent', TRUE, TRUE),
        ('LEGAL', 'BOARD_RESOLUTION', 'Board Resolution', TRUE, TRUE),
        ('LEGAL', 'AUTHORIZATION_LETTER', 'Authorization Letter', TRUE, TRUE),
        ('LEGAL', 'SERVICE_AGREEMENT', 'Service Agreement', TRUE, TRUE),
        ('SUPPORTING', 'STORE_PHOTO', 'Store Photo', TRUE, FALSE),
        ('SUPPORTING', 'QR_IMAGE', 'QR Image', TRUE, FALSE),
        ('SUPPORTING', 'DISPUTE_EVIDENCE', 'Dispute Evidence', TRUE, FALSE),
        ('SUPPORTING', 'SCREENSHOT', 'Screenshot', TRUE, FALSE),
        ('SUPPORTING', 'PHOTO', 'Photo', TRUE, FALSE),
        ('SUPPORTING', 'OTHER', 'Other', TRUE, FALSE)
) AS seed(category_code, type_code, type_name, multiple_allowed, verification_required)
JOIN $TenantSchema.document_category category
    ON category.category_code = seed.category_code
ON CONFLICT (type_code) DO UPDATE SET
    category_id = EXCLUDED.category_id,
    type_name = EXCLUDED.type_name,
    multiple_allowed = EXCLUDED.multiple_allowed,
    verification_required = EXCLUDED.verification_required,
    is_active = EXCLUDED.is_active,
    updated_at = CURRENT_TIMESTAMP;

INSERT INTO $TenantSchema.document_type_entity (document_type_id, entity_type)
SELECT document_type.document_type_id, mapping.entity_type
FROM (
    VALUES
        ('AADHAAR', 'CUSTOMER'), ('AADHAAR', 'AGENT'),
        ('PAN', 'CUSTOMER'), ('PAN', 'MERCHANT'), ('PAN', 'AGENT'),
        ('PASSPORT', 'CUSTOMER'), ('PASSPORT', 'AGENT'),
        ('GST_CERTIFICATE', 'MERCHANT'),
        ('BUSINESS_REGISTRATION', 'MERCHANT'),
        ('NATIONAL_ID', 'CUSTOMER'), ('NATIONAL_ID', 'AGENT'),
        ('TAX_ID', 'CUSTOMER'), ('TAX_ID', 'MERCHANT'), ('TAX_ID', 'AGENT'),
        ('DRIVING_LICENSE', 'CUSTOMER'), ('DRIVING_LICENSE', 'AGENT'),
        ('ADDRESS_PROOF', 'CUSTOMER'), ('ADDRESS_PROOF', 'MERCHANT'), ('ADDRESS_PROOF', 'AGENT'),
        ('SELFIE', 'CUSTOMER'), ('SELFIE', 'AGENT'),
        ('BANK_STATEMENT', 'CUSTOMER'), ('BANK_STATEMENT', 'MERCHANT'),
        ('CANCELLED_CHEQUE', 'MERCHANT'),
        ('INVOICE', 'MERCHANT'), ('INVOICE', 'TRANSACTION'),
        ('RECEIPT', 'TRANSACTION'),
        ('SETTLEMENT_REPORT', 'MERCHANT'),
        ('BANK_ACCOUNT_PROOF', 'CUSTOMER'), ('BANK_ACCOUNT_PROOF', 'MERCHANT'), ('BANK_ACCOUNT_PROOF', 'AGENT'),
        ('MERCHANT_AGREEMENT', 'MERCHANT'),
        ('CUSTOMER_CONSENT', 'CUSTOMER'),
        ('BOARD_RESOLUTION', 'MERCHANT'),
        ('AUTHORIZATION_LETTER', 'MERCHANT'), ('AUTHORIZATION_LETTER', 'AGENT'),
        ('SERVICE_AGREEMENT', 'CUSTOMER'), ('SERVICE_AGREEMENT', 'MERCHANT'), ('SERVICE_AGREEMENT', 'AGENT'),
        ('STORE_PHOTO', 'MERCHANT'),
        ('QR_IMAGE', 'MERCHANT'),
        ('DISPUTE_EVIDENCE', 'TRANSACTION'),
        ('SCREENSHOT', 'CUSTOMER'), ('SCREENSHOT', 'MERCHANT'),
        ('PHOTO', 'CUSTOMER'), ('PHOTO', 'MERCHANT'), ('PHOTO', 'AGENT'),
        ('OTHER', 'CUSTOMER'), ('OTHER', 'MERCHANT'), ('OTHER', 'AGENT')
) AS mapping(type_code, entity_type)
JOIN $TenantSchema.document_type document_type
    ON document_type.type_code = mapping.type_code
ON CONFLICT (document_type_id, entity_type) DO NOTHING;

CREATE TABLE IF NOT EXISTS $TenantSchema.auth_challenge (
    challenge_id UUID PRIMARY KEY,
    account_id TEXT,
    challenge_value TEXT NOT NULL,
    challenge_type VARCHAR(30) NOT NULL,
    issued_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    expires_at TIMESTAMP NOT NULL,
    used BOOLEAN DEFAULT FALSE,
    used_at TIMESTAMP,
    ip_address VARCHAR(50),
    status VARCHAR(20) DEFAULT 'ACTIVE',
    CONSTRAINT fk_auth_challenge_account FOREIGN KEY (account_id) REFERENCES $TenantSchema.account(account_id)
);

CREATE TABLE IF NOT EXISTS $TenantSchema.error_catalog (
    id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    error_code VARCHAR(100) NOT NULL,
    language_code VARCHAR(10) NOT NULL,
    message_template TEXT NOT NULL,
    http_status INT NOT NULL DEFAULT 400 CHECK (http_status BETWEEN 100 AND 599),
    category VARCHAR(30),
    module VARCHAR(30),
    is_active BOOLEAN NOT NULL DEFAULT TRUE,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_by TEXT,
    CONSTRAINT uq_error_catalog_code_language UNIQUE (error_code, language_code)
);

ALTER TABLE $TenantSchema.error_catalog
    ADD COLUMN IF NOT EXISTS language_code VARCHAR(10),
    ADD COLUMN IF NOT EXISTS message_template TEXT,
    ADD COLUMN IF NOT EXISTS http_status INT DEFAULT 400,
    ADD COLUMN IF NOT EXISTS category VARCHAR(30),
    ADD COLUMN IF NOT EXISTS module VARCHAR(30),
    ADD COLUMN IF NOT EXISTS is_active BOOLEAN DEFAULT TRUE,
    ADD COLUMN IF NOT EXISTS updated_by TEXT;

DO `$`$
BEGIN
    IF EXISTS (
        SELECT 1
        FROM information_schema.columns
        WHERE table_schema = '$TenantSchema'
          AND table_name = 'error_catalog'
          AND column_name = 'language'
    ) THEN
        EXECUTE 'UPDATE $TenantSchema.error_catalog SET language_code = COALESCE(language_code, language)';
    END IF;

    IF EXISTS (
        SELECT 1
        FROM information_schema.columns
        WHERE table_schema = '$TenantSchema'
          AND table_name = 'error_catalog'
          AND column_name = 'message'
    ) THEN
        EXECUTE 'UPDATE $TenantSchema.error_catalog SET message_template = COALESCE(message_template, message)';
    END IF;

    IF EXISTS (
        SELECT 1
        FROM information_schema.columns
        WHERE table_schema = '$TenantSchema'
          AND table_name = 'error_catalog'
          AND column_name = 'status'
    ) THEN
        EXECUTE 'UPDATE $TenantSchema.error_catalog SET is_active = COALESCE(is_active, status = ''ACTIVE'')';
    END IF;
END
`$`$;

UPDATE $TenantSchema.error_catalog
SET http_status = COALESCE(http_status, 400),
    is_active = COALESCE(is_active, TRUE),
    updated_at = COALESCE(updated_at, CURRENT_TIMESTAMP);

CREATE UNIQUE INDEX IF NOT EXISTS uq_error_catalog_code_language
    ON $TenantSchema.error_catalog (error_code, language_code);

CREATE INDEX IF NOT EXISTS idx_error_catalog_lookup
    ON $TenantSchema.error_catalog (error_code, language_code);

