UPDATE $TenantSchema.enumerations child
SET parent_enum_id = parent.id,
    updated_at = CURRENT_TIMESTAMP
FROM (
    VALUES
        ('ELEC', 'UTILITIES'),
        ('WATER', 'UTILITIES'),
        ('PGAS', 'UTILITIES'),
