        ('BUSPASS', 'GOVERNMENT_TRANSPORT'),
        ('OTT', 'LIFESTYLE_SUBSCRIPTIONS_DONATIONS'),
        ('SAAS', 'LIFESTYLE_SUBSCRIPTIONS_DONATIONS'),
        ('CLUB', 'LIFESTYLE_SUBSCRIPTIONS_DONATIONS'),
        ('DONATE', 'LIFESTYLE_SUBSCRIPTIONS_DONATIONS'),
        ('EV', 'LIFESTYLE_SUBSCRIPTIONS_DONATIONS'),
        ('GYM', 'LIFESTYLE_SUBSCRIPTIONS_DONATIONS')
) AS mapping(child_code, parent_code)
JOIN $TenantSchema.enumerations parent
    ON parent.enum_type = 'BILLER_CATEGORY'
   AND parent.enum_code = mapping.parent_code
WHERE child.enum_type = 'BILLER_SUB_CATEGORY'
  AND child.enum_code = mapping.child_code;

