        ('ZA', 'ZA-GT', 'Johannesburg', 'PPLA-ZA-06', -26.20227, 28.04363, 'Africa/Johannesburg'),
        ('ZA', 'ZA-FS', 'Bloemfontein', 'PPLA-ZA-03', -29.12107, 26.214, 'Africa/Johannesburg'),
        ('ZA', 'ZA-EC', 'Bhisho', 'PPLA-ZA-05', -32.84721, 27.44218, 'Africa/Johannesburg'),
        ('ZA', 'ZA-WC', 'Cape Town', 'PPLA-ZA-11', -33.92584, 18.42322, 'Africa/Johannesburg'),
        ('ZM', 'ZM-06', 'Solwezi', 'PPLA-ZM-06', -12.1688, 26.38938, 'Africa/Lusaka'),
        ('ZM', 'ZM-08', 'Ndola', 'PPLA-ZM-08', -12.95867, 28.63659, 'Africa/Lusaka'),
        ('ZM', 'ZM-10', 'Chinsali', 'PPLA-ZM-10', -10.54142, 32.08162, 'Africa/Lusaka'),
        ('ZW', 'ZW-MA', 'Mutare', 'PPLA-ZW-01', -18.9707, 32.67086, 'Africa/Harare'),
        ('ZW', 'ZW-MN', 'Lupane', 'PPLA-ZW-06', -18.93149, 27.80696, 'Africa/Harare'),
        ('ZW', 'ZW-MW', 'Chinhoyi', 'PPLA-ZW-05', -17.36667, 30.2, 'Africa/Harare'),
        ('ZW', 'ZW-BU', 'Bulawayo', 'PPLA-ZW-09', -20.15, 28.58333, 'Africa/Harare'),
        ('ZW', 'ZW-MC', 'Bindura', 'PPLA-ZW-03', -17.30192, 31.33056, 'Africa/Harare')
) AS data(country_code, subdivision_code, name, code, latitude, longitude, timezone)
JOIN $TenantSchema.enumerations country
    ON country.enum_type = 'COUNTRY'
   AND country.enum_code = data.country_code
LEFT JOIN $TenantSchema.country_subdivision subdivision
    ON subdivision.country_id = country.id
   AND subdivision.code = data.subdivision_code
ORDER BY country.id, COALESCE(subdivision.id, 0), data.code, data.name
ON CONFLICT (country_id, (COALESCE(subdivision_id, 0)), code) WHERE code IS NOT NULL DO UPDATE
SET name = EXCLUDED.name,
    latitude = EXCLUDED.latitude,
    longitude = EXCLUDED.longitude,
    timezone = EXCLUDED.timezone,
    status = 'ACTIVE',
    updated_at = CURRENT_TIMESTAMP;
